const workshopCustomerContentJson = r'''{"schema":1,"revision":"customer-content-20261016-1","source":"21_손님캐릭터와관계시스템.md","npcs":[{"id":"npc_yunha","reference_name":"정윤하","display_name":"퇴근길 윤하 씨","address_default":"윤하 씨","address_note":"동일","appearance":"턱선 검은 단발, 처진 눈매, 베이지 코트, 운동화, 주머니 속 사원증","personality":"말수가 적고 관찰력이 좋음. 퇴근길 한 정거장 먼저 내려 방문","order_tendency":"바삭한 팥 선호. 평소 2개, 가끔 슈크림 추가","action":"가방을 고쳐 메고 봉투를 받으면 어깨 힘을 풂","expressions":{"waiting":"가방 끈을 고쳐 멤","happy":"어깨 힘을 풀고 작게 웃음","disappointed":"메뉴판을 한 번 더 봄","close":"먼저 목례하고 휴대전화를 내려둠"},"dialogues":[{"id":"yunha_first_visit_01","event":"first_visit","text":"팥 두 개 주세요. 하나는 지금 먹을게요.","requires_context_qualification":true,"once_only":true},{"id":"yunha_order_01","event":"order","text":"안녕하세요. 오늘도 팥 두 개요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_smalltalk_01","event":"smalltalk","text":"오늘은 슈크림 먹어볼까요. ……팥 하나랑 슈크림 하나 주세요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_waiting_01","event":"waiting","text":"천천히 주세요. 여기서 잠깐 쉬고 있으려고요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_delayed_01","event":"delayed","text":"버스가 곧 오네요. 얼마나 더 걸릴까요?","requires_context_qualification":true,"once_only":false},{"id":"yunha_success_01","event":"success","text":"꼬리 바삭하네요. 이 부분이 제일 좋아요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_corrected_01","event":"corrected","text":"네, 이거예요. 바꿔주셔서 감사해요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_wrong_order_01","event":"wrong_order","text":"저 팥으로 부탁드렸어요. 바꿔주실 수 있을까요?","requires_context_qualification":true,"once_only":false},{"id":"yunha_sold_out_01","event":"sold_out","text":"아, 늦었구나. 다음에는 조금 일찍 와야겠네요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_cancel_before_cooking_01","event":"cancel_before_cooking","text":"회사에서 연락이 와서요. 아직 안 구우셨으면 다음에 올게요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_timeout_01","event":"timeout","text":"이제 가봐야겠어요. 다음에 다시 들를게요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_return_after_gap_01","event":"return_after_gap","text":"며칠 못 왔네요. 저녁마다 여기 생각은 났는데.","requires_context_qualification":true,"once_only":true},{"id":"yunha_rain_01","event":"rain","text":"우산 접다가 소매가 다 젖었어요. 붕어빵은 안 젖게 잘 부탁드려요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_cold_01","event":"cold","text":"봉투가 따뜻해서 주머니에 손 넣을 필요가 없네요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_new_menu_01","event":"new_menu","text":"새로 나온 거 하나 주세요. 평소 먹던 것도 하나 주시고요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_friendly_01","event":"friendly","text":"앞치마 바꾸셨네요. 지난번 것보다 잘 어울려요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_regular_01","event":"regular","text":"오늘 별일은 없었어요. 그냥 들르고 싶어서요.","requires_context_qualification":true,"once_only":false},{"id":"yunha_neighbor_01","event":"neighbor","text":"막례 할머니가 저 기다리셨다고요? 다음에 복덕방에 인사드려야겠네요.","requires_context_qualification":true,"once_only":false}],"dialogue_notes":"앞치마 변경 대사는 실제 외형 변경 이후 1회만 사용한다. 저녁과 버스 대사는 해당 시간대와 버스 설정에 맞게 사용한다."},{"id":"npc_doyun","reference_name":"김도윤","display_name":"노란 가방 도윤이","address_default":"도윤아","address_note":"동일","appearance":"동그란 안경, 빠진 앞니 하나, 노란 책가방","personality":"호기심 많은 초등학생. 문방구집 손자이며 동네 간식 지도를 그림","order_tendency":"슈크림 선호. 평소 1개","action":"발뒤꿈치를 들썩이며 틀을 관찰","expressions":{"waiting":"발뒤꿈치를 들썩임","happy":"붕어빵을 눈높이로 듦","disappointed":"가방 끈을 잡고 발끝을 봄","close":"공책을 펼쳐 보여줌"},"dialogues":[{"id":"doyun_first_visit_01","event":"first_visit","text":"슈크림 하나 주세요! 이 돈이면 되죠?","requires_context_qualification":true,"once_only":true},{"id":"doyun_order_01","event":"order","text":"사장님! 오늘도 슈크림이요!","requires_context_qualification":true,"once_only":false},{"id":"doyun_smalltalk_01","event":"smalltalk","text":"팥도 먹어봐야 하는데…… 슈크림이 서운해할 것 같아요.","requires_context_qualification":true,"once_only":false},{"id":"doyun_waiting_01","event":"waiting","text":"몇 번 뒤집어야 다 익어요? 제가 세어봐도 돼요?","requires_context_qualification":true,"once_only":false},{"id":"doyun_delayed_01","event":"delayed","text":"아직이에요? 저 시계 안 보려고 했는데 벌써 세 번 봤어요.","requires_context_qualification":true,"once_only":false},{"id":"doyun_success_01","event":"success","text":"와! 오늘 건 꼬리가 엄청 길어요!","requires_context_qualification":true,"once_only":false},{"id":"doyun_corrected_01","event":"corrected","text":"맞아요, 슈크림! 이번엔 안 헷갈렸어요.","requires_context_qualification":true,"once_only":false},{"id":"doyun_wrong_order_01","event":"wrong_order","text":"앗, 이건 팥이에요. 제 슈크림은 아직 틀 안에 있어요?","requires_context_qualification":true,"once_only":false},{"id":"doyun_sold_out_01","event":"sold_out","text":"슈크림도요? 진짜요? ……그럼 다음에는 일찍 올게요.","requires_context_qualification":true,"once_only":false},{"id":"doyun_cancel_before_cooking_01","event":"cancel_before_cooking","text":"학원 차 왔어요! 아직 안 만드셨으면 다음에 먹을게요!","requires_context_qualification":true,"once_only":false},{"id":"doyun_timeout_01","event":"timeout","text":"저 이제 가야 돼요! 다음에는 더 일찍 올게요!","requires_context_qualification":true,"once_only":false},{"id":"doyun_return_after_gap_01","event":"return_after_gap","text":"저 할머니 집 갔다 왔어요! 거기도 붕어빵집 있는데 맛이 달라요.","requires_context_qualification":true,"once_only":true},{"id":"doyun_rain_01","event":"rain","text":"우산은 작은데 가방은 커서요. 제 등만 다 젖었어요.","requires_context_qualification":true,"once_only":false},{"id":"doyun_cold_01","event":"cold","text":"후우 하면 김 나와요! 붕어빵이랑 저랑 똑같아요.","requires_context_qualification":true,"once_only":false},{"id":"doyun_new_menu_01","event":"new_menu","text":"새 맛 이름 알려주세요! 제 간식 지도에 적어야 해요.","requires_context_qualification":true,"once_only":false},{"id":"doyun_friendly_01","event":"friendly","text":"학교에서 우리 동네 그리라길래 여기 그렸어요. 사장님도 있어요!","requires_context_qualification":true,"once_only":true},{"id":"doyun_regular_01","event":"regular","text":"오늘 친구 데려왔어요. 제가 맨날 말한 가게가 여기예요!","requires_context_qualification":true,"once_only":false},{"id":"doyun_neighbor_01","event":"neighbor","text":"태오 형은 또 사진 못 찍었대요? 제가 먹기 전에 찍으라고 했는데!","requires_context_qualification":true,"once_only":false}],"dialogue_notes":"친구 동행, 학교 그림, 외출 사연은 해당 이벤트에서 사용한다. 동행 이벤트가 없으면 단골 대체 대사 ‘제 지도에서 여기는 별 세 개예요. 원래 최고는 두 개인데!’를 사용한다."},{"id":"npc_makrye","reference_name":"박막례","display_name":"복덕방 막례 할머니","address_default":"막례 할머니","address_note":"동일","appearance":"은빛 곱슬머리, 자주색 조끼, 꽃무늬 장바구니, 안경줄","personality":"행복부동산 운영. 이웃 몫을 먼저 챙기며 자기 몫은 빼먹음","order_tendency":"팥 선호. 4~5개를 나눠 포장","action":"손가락을 접으며 개수를 세고 봉투를 장바구니 위에 놓음","expressions":{"waiting":"손가락으로 수량을 셈","happy":"눈가에 주름이 잡히며 웃음","disappointed":"손을 가볍게 내저음","close":"자기 몫을 가게 앞에서 먹음"},"dialogues":[{"id":"makrye_first_visit_01","event":"first_visit","text":"새로 열었구먼. 팥 네 개 줘봐요. 옆 가게 사람들이랑 먹게.","requires_context_qualification":true,"once_only":true},{"id":"makrye_order_01","event":"order","text":"사장님, 나 왔어요. 오늘은 팥 다섯 개.","requires_context_qualification":true,"once_only":false},{"id":"makrye_smalltalk_01","event":"smalltalk","text":"윗집은 슈크림이고, 옆집은 팥이고…… 잠깐, 내가 적어왔는데.","requires_context_qualification":true,"once_only":false},{"id":"makrye_waiting_01","event":"waiting","text":"구워요, 구워. 나 장바구니 정리하고 있을 테니.","requires_context_qualification":true,"once_only":false},{"id":"makrye_delayed_01","event":"delayed","text":"오늘 손님이 많네. 내 것 굽는 건 안 잊었지?","requires_context_qualification":true,"once_only":false},{"id":"makrye_success_01","event":"success","text":"꼬리까지 야무지게 구웠네. 잘 먹을게요.","requires_context_qualification":true,"once_only":false},{"id":"makrye_corrected_01","event":"corrected","text":"그래, 이렇게 맞네. 다시 챙겨줘서 고마워요.","requires_context_qualification":true,"once_only":false},{"id":"makrye_wrong_order_01","event":"wrong_order","text":"이 봉투만 바뀌었어요. 섞이기 전에 같이 세어봅시다.","requires_context_qualification":true,"once_only":false},{"id":"makrye_sold_out_01","event":"sold_out","text":"다 팔았어? 잘됐네. 그럼 사장님도 잠깐 쉬어요.","requires_context_qualification":true,"once_only":false},{"id":"makrye_cancel_before_cooking_01","event":"cancel_before_cooking","text":"집 보러 온 사람이 도착했대. 아직 안 구웠으면 다음에 줘요.","requires_context_qualification":true,"once_only":false},{"id":"makrye_timeout_01","event":"timeout","text":"내가 손님 만날 시간이 됐네. 오늘은 먼저 가봐야겠어요.","requires_context_qualification":true,"once_only":false},{"id":"makrye_return_after_gap_01","event":"return_after_gap","text":"내가 며칠 안 보였지? 딸네 갔다 왔어요. 가게는 잘됐고?","requires_context_qualification":true,"once_only":true},{"id":"makrye_rain_01","event":"rain","text":"입구에 물 고였네. 넘어지기 전에 내가 우산 좀 옮겨둘게.","requires_context_qualification":true,"once_only":false},{"id":"makrye_cold_01","event":"cold","text":"나는 장갑이라도 끼지. 사장님은 손 안 시려요?","requires_context_qualification":true,"once_only":false},{"id":"makrye_new_menu_01","event":"new_menu","text":"이건 무슨 맛이에요? 내가 알아야 다른 사람한테도 말해주지.","requires_context_qualification":true,"once_only":false},{"id":"makrye_friendly_01","event":"friendly","text":"사장님 것도 하나 구워 먹어요. 남 먹는 것만 보고 있지 말고.","requires_context_qualification":true,"once_only":false},{"id":"makrye_regular_01","event":"regular","text":"오늘 하나는 봉투에 넣지 마요. 여기서 먹고 갈 거야.","requires_context_qualification":true,"once_only":false},{"id":"makrye_neighbor_01","event":"neighbor","text":"수아 씨가 여기 알려줘서 고맙다더라. 이제 동네가 좀 익숙해졌나 봐.","requires_context_qualification":true,"once_only":false}],"dialogue_notes":"첫 방문 대사는 가게 개업 초기에만 사용한다. 이후 처음 등장하면 ‘여기가 그 붕어빵집이구먼. 팥 네 개 줘봐요.’로 대체한다. 분리 포장이 없으면 실수 대사는 ‘주문이 조금 다르네. 같이 다시 세어봅시다.’를 사용한다."},{"id":"npc_seojin","reference_name":"오서진","display_name":"옥탑방 오 작가","address_default":"오 작가님","address_note":"서진 씨","appearance":"느슨하게 묶은 갈색 머리, 남색 후드, 물감 묻은 가방, 수첩과 연필","personality":"옥탑방에서 작업하는 그림 작가. 조용하고 엉뚱한 관찰을 함","order_tendency":"슈크림 선호. 평소 1개","action":"양면을 관찰하고 수첩을 덮은 뒤 먹음","expressions":{"waiting":"수첩에 스케치","happy":"수첩을 덮고 음식에 집중","disappointed":"연필로 수첩 모서리를 두드림","close":"완성한 그림을 꺼냄"},"dialogues":[{"id":"seojin_first_visit_01","event":"first_visit","text":"슈크림 하나요. 기다리는 동안 가게 조금 그려도 될까요?","requires_context_qualification":true,"once_only":true},{"id":"seojin_order_01","event":"order","text":"안녕하세요. 슈크림 하나 부탁드려요.","requires_context_qualification":true,"once_only":false},{"id":"seojin_smalltalk_01","event":"smalltalk","text":"오늘은 팥 냄새가 더 좋네요. 냄새 따라 골라도 되겠죠?","requires_context_qualification":true,"once_only":false},{"id":"seojin_waiting_01","event":"waiting","text":"틀 열 때마다 김 모양이 달라요. 방금 건 나무 같았는데.","requires_context_qualification":true,"once_only":false},{"id":"seojin_delayed_01","event":"delayed","text":"스케치를 다 했네요. 붕어빵은 얼마나 더 걸릴까요?","requires_context_qualification":true,"once_only":false},{"id":"seojin_success_01","event":"success","text":"색 예쁘다. ……아, 오늘은 식기 전에 먹을게요.","requires_context_qualification":true,"once_only":false},{"id":"seojin_corrected_01","event":"corrected","text":"네, 슈크림. 감사합니다.","requires_context_qualification":true,"once_only":false},{"id":"seojin_wrong_order_01","event":"wrong_order","text":"저 슈크림이었어요. 이건 다른 분 것일까요?","requires_context_qualification":true,"once_only":false},{"id":"seojin_sold_out_01","event":"sold_out","text":"빈 틀은 처음 보네요. 오늘은 가게도 쉬는 모습으로 그려야겠다.","requires_context_qualification":true,"once_only":false},{"id":"seojin_cancel_before_cooking_01","event":"cancel_before_cooking","text":"작업실에서 연락이 왔어요. 아직 안 구우셨으면 다음에 부탁드릴게요.","requires_context_qualification":true,"once_only":false},{"id":"seojin_timeout_01","event":"timeout","text":"작업하러 들어가야겠어요. 다음에 다시 올게요.","requires_context_qualification":true,"once_only":false},{"id":"seojin_return_after_gap_01","event":"return_after_gap","text":"마감 끝났어요. 며칠 만에 여유 있게 나왔네요.","requires_context_qualification":true,"once_only":true},{"id":"seojin_rain_01","event":"rain","text":"물웅덩이에 간판이 비쳐요. 저쪽에서 보면 가게가 두 개예요.","requires_context_qualification":true,"once_only":false},{"id":"seojin_cold_01","event":"cold","text":"연필 잡던 손이 안 펴지네요. 봉투 좀 쥐고 있어야겠어요.","requires_context_qualification":true,"once_only":false},{"id":"seojin_new_menu_01","event":"new_menu","text":"반으로 갈랐을 때 안쪽이 궁금해요. 하나 주세요.","requires_context_qualification":true,"once_only":false},{"id":"seojin_friendly_01","event":"friendly","text":"머리에 연필 있다고요? 아…… 한참 찾았는데.","requires_context_qualification":true,"once_only":false},{"id":"seojin_regular_01","event":"regular","text":"가게 그림 가져왔어요. 여기 놓고 가도 될까요?","requires_context_qualification":true,"once_only":true},{"id":"seojin_neighbor_01","event":"neighbor","text":"도윤이가 그림 검사했어요. 자기 가방 색이 틀렸대서 고쳤어요.","requires_context_qualification":true,"once_only":true}],"dialogue_notes":"그림 선물은 1회 이벤트다. 이벤트 완료 후 반복 단골 대사는 ‘저번 그림은 마음에 드셨어요? 다음에는 다른 계절로 그려볼까 봐요.’를 사용한다."},{"id":"npc_taeo","reference_name":"강태오","display_name":"사진쟁이 태오 총각","address_default":"태오 씨","address_note":"동일","appearance":"주황 비니, 짧은 곱슬머리, 청재킷, 작은 카메라","personality":"동네 간식을 기록하는 대학생. 촬영 허락을 구하지만 자주 먹는 게 먼저","order_tendency":"신메뉴 선호. 없으면 팥과 슈크림 중 선택","action":"촬영 자세를 잡다가 냄새에 이끌려 먼저 한입","expressions":{"waiting":"카메라 설정을 만짐","happy":"촬영을 잊고 한입 먹음","disappointed":"카메라 덮개를 닫음","close":"카메라를 가방에 넣고 방문"},"dialogues":[{"id":"taeo_first_visit_01","event":"first_visit","text":"추천하는 맛으로 하나 주세요! 음식 사진 찍어도 괜찮을까요?","requires_context_qualification":true,"once_only":true},{"id":"taeo_order_01","event":"order","text":"사장님, 오늘 제일 잘 나온 붕어 한 마리 부탁드립니다!","requires_context_qualification":true,"once_only":false},{"id":"taeo_smalltalk_01","event":"smalltalk","text":"사진은 두 개가 예쁜데…… 네, 제가 두 개 먹고 싶은 거예요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_waiting_01","event":"waiting","text":"틀 여는 장면 찍어도 돼요? 손만 나오게 할게요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_delayed_01","event":"delayed","text":"사진 고르다가 시간 가는 줄 몰랐네요. 제 건 아직이죠?","requires_context_qualification":true,"once_only":false},{"id":"taeo_success_01","event":"success","text":"와, 냄새 좋다. ……아! 또 사진 전에 먹었네.","requires_context_qualification":true,"once_only":false},{"id":"taeo_corrected_01","event":"corrected","text":"감사합니다! 이번에는 사진도 제대로 찍었어요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_wrong_order_01","event":"wrong_order","text":"앗, 팥으로 주문했어요. 바꿔주시면 이번엔 꼭 사진부터 찍을게요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_sold_out_01","event":"sold_out","text":"오늘은 빈 봉투라도 찍어야겠네요. 늦게 온 사람의 결말.","requires_context_qualification":true,"once_only":false},{"id":"taeo_cancel_before_cooking_01","event":"cancel_before_cooking","text":"약속 시간이 다 됐어요. 아직 안 구우셨으면 다음에 다시 올게요!","requires_context_qualification":true,"once_only":false},{"id":"taeo_timeout_01","event":"timeout","text":"약속에 늦겠어요. 오늘은 먼저 가볼게요!","requires_context_qualification":true,"once_only":false},{"id":"taeo_return_after_gap_01","event":"return_after_gap","text":"시험 끝났습니다! 이제 붕어빵 먹을 시간 생겼어요.","requires_context_qualification":true,"once_only":true},{"id":"taeo_rain_01","event":"rain","text":"비 때문에 촬영은 접었는데 붕어빵은 포기 못 하겠더라고요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_cold_01","event":"cold","text":"손 떨려서 사진이 다 흔들려요. 일단 먹고 다시 생각할게요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_new_menu_01","event":"new_menu","text":"신메뉴요? 잠깐만요. 이번에는 진짜 카메라부터 켤게요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_friendly_01","event":"friendly","text":"오늘은 카메라 두고 왔어요. 그냥 먹으면서 얘기하려고요.","requires_context_qualification":true,"once_only":false},{"id":"taeo_regular_01","event":"regular","text":"소개 글 썼어요. 올리기 전에 사장님도 한번 봐주세요.","requires_context_qualification":true,"once_only":true},{"id":"taeo_neighbor_01","event":"neighbor","text":"막례 할머니가 제 이름보다 사진쟁이를 더 크게 부르세요. 이제 저도 바로 돌아봐요.","requires_context_qualification":true,"once_only":false}],"dialogue_notes":"소개 글은 게임 속 이야기다. 실제 SNS 게시나 계정 연동 기능을 뜻하지 않는다. 팥 실수 대사는 팥 주문일 때만 선택하며, 일반 주문 문구와 별개로 주문 UI에는 실제 맛을 명시한다."},{"id":"npc_eunchae","reference_name":"한은채","display_name":"밤근무 은채 씨","address_default":"은채 씨","address_note":"동일","appearance":"짧게 묶은 머리, 초록 점퍼, 편한 운동화, 달 열쇠고리","personality":"야간 근무자. 퇴근 후 아침에 들르고 휴일에는 낮에도 방문","order_tendency":"부드러운 슈크림 선호. 평소 2개","action":"반쯤 감긴 눈으로 기다리다 봉투를 두 손으로 감쌈","expressions":{"waiting":"눈을 잠깐 감음","happy":"봉투를 두 손으로 감쌈","disappointed":"눈을 비비지 않고 천천히 깜빡임","close":"쉬는 날 또렷한 눈으로 먼저 인사"},"dialogues":[{"id":"eunchae_first_visit_01","event":"first_visit","text":"아침에도 여시네요. 슈크림 두 개 부탁드려요.","requires_context_qualification":true,"once_only":true},{"id":"eunchae_order_01","event":"order","text":"안녕하세요. 퇴근하고 왔어요. 오늘도 두 개요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_smalltalk_01","event":"smalltalk","text":"오늘은 뭘 먹을까요. 아직 머리가 반쯤 자고 있어서요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_waiting_01","event":"waiting","text":"따뜻하네요, 여기. 잠깐 바람 피하고 있을게요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_delayed_01","event":"delayed","text":"저 잠깐 눈 감고 있었네요. 제 것 나오면 불러주세요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_success_01","event":"success","text":"따뜻하다. 감사합니다. 집 가서 바로 먹어야겠어요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_corrected_01","event":"corrected","text":"감사합니다. 이제 집에 가서 맛있게 먹을게요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_wrong_order_01","event":"wrong_order","text":"저 슈크림으로 부탁드렸어요. 바꿔주실 수 있을까요?","requires_context_qualification":true,"once_only":false},{"id":"eunchae_sold_out_01","event":"sold_out","text":"벌써 다 나갔어요? 오늘 동네가 저보다 부지런했네요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_cancel_before_cooking_01","event":"cancel_before_cooking","text":"너무 졸려서 먼저 들어가야겠어요. 아직 안 구우셨으면 취소 부탁드려요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_timeout_01","event":"timeout","text":"이제 들어가서 쉬어야겠어요. 다음에 들를게요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_return_after_gap_01","event":"return_after_gap","text":"근무 시간이 바뀌어서 못 왔어요. 오늘은 시간이 맞았네요.","requires_context_qualification":true,"once_only":true},{"id":"eunchae_rain_01","event":"rain","text":"버스에서 안 졸고 잘 내렸는데, 우산을 놓고 왔어요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_cold_01","event":"cold","text":"봉투 잡으니까 손끝에 감각이 돌아오네요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_new_menu_01","event":"new_menu","text":"새 맛이네요. 집에서 천천히 먹어볼게요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_friendly_01","event":"friendly","text":"사장님은 몇 시에 일어나세요? 제가 퇴근할 때 이미 열려 있길래.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_regular_01","event":"regular","text":"오늘 쉬는 날이에요. 안 졸릴 때도 와보고 싶었어요.","requires_context_qualification":true,"once_only":false},{"id":"eunchae_neighbor_01","event":"neighbor","text":"민재 씨는 이 시간에도 뛰시네요. 저는 집까지 걷는 걸로 충분해요.","requires_context_qualification":true,"once_only":false}],"dialogue_notes":"시간대 기능이 없거나 아침이 아니면 첫 방문을 ‘여기가 그 붕어빵집이네요. 슈크림 두 개 부탁드려요.’로 대체한다. 휴일 방문에서는 퇴근·졸림 대사를 제외한다."},{"id":"npc_minjae","reference_name":"최민재","display_name":"한 바퀴 최 씨","address_default":"민재 씨","address_note":"동일","appearance":"파란 바람막이, 검은 운동 바지, 비뚤어진 헤어밴드, 운동 시계","personality":"러닝 초보. 가게를 반환점으로 정하고 나중에는 운동 없이도 방문","order_tendency":"팥 선호. 하나 고민하다 2개 주문","action":"숨을 고르고 시계를 멈춘 뒤 스트레칭","expressions":{"waiting":"가벼운 스트레칭","happy":"시계를 멈추고 웃음","disappointed":"시계와 틀을 번갈아 봄","close":"평상복으로 방문"},"dialogues":[{"id":"minjae_first_visit_01","event":"first_visit","text":"팥 하나요. 후…… 잠깐만요, 숨 좀 고르고요.","requires_context_qualification":true,"once_only":true},{"id":"minjae_order_01","event":"order","text":"한 바퀴 돌고 왔습니다! 팥 두 개 주세요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_smalltalk_01","event":"smalltalk","text":"하나는 지금 먹고, 하나는 집에서 먹고. 네, 두 개요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_waiting_01","event":"waiting","text":"기다리는 동안 스트레칭 좀 할게요. 여기 서 있어도 괜찮죠?","requires_context_qualification":true,"once_only":false},{"id":"minjae_delayed_01","event":"delayed","text":"다리 다 풀었는데 시간이 남네요. 제 건 얼마나 더 걸릴까요?","requires_context_qualification":true,"once_only":false},{"id":"minjae_success_01","event":"success","text":"오늘 이거 생각하면서 마지막 언덕 올라왔어요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_corrected_01","event":"corrected","text":"맞아요, 팥! 이제 집까지 잘 들고 가볼게요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_wrong_order_01","event":"wrong_order","text":"이건 슈크림이네요. 오늘은 팥 먹을 생각으로 왔거든요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_sold_out_01","event":"sold_out","text":"반환점까지는 잘 왔는데. 다음에는 코스를 반대로 돌아야겠다.","requires_context_qualification":true,"once_only":false},{"id":"minjae_cancel_before_cooking_01","event":"cancel_before_cooking","text":"땀이 식어서 먼저 들어가야겠어요. 아직 안 구우셨으면 다음에 먹을게요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_timeout_01","event":"timeout","text":"몸이 식어서 이제 가봐야겠어요. 다음에 또 올게요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_return_after_gap_01","event":"return_after_gap","text":"운동 며칠 쉬었더니 여기 오는 길이 더 길어진 것 같아요.","requires_context_qualification":true,"once_only":true},{"id":"minjae_rain_01","event":"rain","text":"오늘은 운동 쉬어요. 붕어빵 사러 걷는 건 별개고요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_cold_01","event":"cold","text":"돌아갈 때는 걸어야겠어요. 뛰면 붕어빵이 다 부서지겠네.","requires_context_qualification":true,"once_only":false},{"id":"minjae_new_menu_01","event":"new_menu","text":"새 맛이요? 오늘 코스 늘린 보람이 있네요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_friendly_01","event":"friendly","text":"시계에 여기 저장했어요. 위치 이름은 붕어빵 반환점이에요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_regular_01","event":"regular","text":"오늘 안 뛰었어요. 그냥 먹고 싶어서 나왔어요.","requires_context_qualification":true,"once_only":false},{"id":"minjae_neighbor_01","event":"neighbor","text":"도윤이가 저보고 매일 경주하냐고 묻더라고요. 붕어빵 식기 전에 집 가는 경주라니까 웃던데요.","requires_context_qualification":true,"once_only":false}],"dialogue_notes":"단골 평상복 방문에서는 숨 고르기, 땀, 러닝 성취 대사를 제외한다. 대체 주문은 ‘오늘은 산책만 했어요. 팥 두 개 주세요.’, 대체 성공은 ‘안 뛰고 먹어도 똑같이 맛있네요.’로 한다."},{"id":"npc_sua","reference_name":"이수아","display_name":"새 이웃 수아 씨","address_default":"수아 씨","address_note":"이벤트 후 우리 동네 수아 씨","appearance":"긴 검은 머리, 연보라 카디건, 크림 천가방, 토끼 장식","personality":"새로 이사 온 이웃. 낯을 가리지만 익숙해지면 먼저 말을 건넴","order_tendency":"슈크림 선호. 친해지면 팥도 시도","action":"가방 손잡이를 쥐다가 나중에는 멀리서 손인사","expressions":{"waiting":"가방 손잡이를 쥠","happy":"봉투를 보며 작게 웃음","disappointed":"잠깐 머뭇거림","close":"멀리서 손인사"},"dialogues":[{"id":"sua_first_visit_01","event":"first_visit","text":"저…… 슈크림 하나 주세요.","requires_context_qualification":true,"once_only":true},{"id":"sua_order_01","event":"order","text":"안녕하세요. 오늘도 슈크림으로 주세요.","requires_context_qualification":true,"once_only":false},{"id":"sua_smalltalk_01","event":"smalltalk","text":"조금만 더 봐도 될까요? 다른 맛도 먹어보고 싶어서요.","requires_context_qualification":true,"once_only":false},{"id":"sua_waiting_01","event":"waiting","text":"굽는 거 구경해도 돼요? 뒤집을 때가 재밌네요.","requires_context_qualification":true,"once_only":false},{"id":"sua_delayed_01","event":"delayed","text":"저기…… 제 주문 들어간 거 맞을까요?","requires_context_qualification":true,"once_only":false},{"id":"sua_success_01","event":"success","text":"감사합니다. 와, 오늘 건 꼬리까지 통통하네요.","requires_context_qualification":true,"once_only":false},{"id":"sua_corrected_01","event":"corrected","text":"네, 이거예요. 바꿔주셔서 감사해요.","requires_context_qualification":true,"once_only":false},{"id":"sua_wrong_order_01","event":"wrong_order","text":"혹시 이거 팥인가요? 저는 슈크림으로 부탁드렸는데요.","requires_context_qualification":true,"once_only":false},{"id":"sua_sold_out_01","event":"sold_out","text":"아쉽네요. 다음에는 조금 일찍 와볼게요.","requires_context_qualification":true,"once_only":false},{"id":"sua_cancel_before_cooking_01","event":"cancel_before_cooking","text":"택배 기사님이 오셨대서요. 아직 안 구우셨으면 다음에 다시 올게요.","requires_context_qualification":true,"once_only":false},{"id":"sua_timeout_01","event":"timeout","text":"이제 들어가 봐야 할 것 같아요. 다음에 다시 올게요.","requires_context_qualification":true,"once_only":false},{"id":"sua_return_after_gap_01","event":"return_after_gap","text":"본가에 다녀왔어요. 돌아오는 길에 여기부터 들렀어요.","requires_context_qualification":true,"once_only":true},{"id":"sua_rain_01","event":"rain","text":"우산 여기 놓아도 될까요? 가게 안에 물 떨어질까 봐요.","requires_context_qualification":true,"once_only":false},{"id":"sua_cold_01","event":"cold","text":"집에 있었는데 붕어빵 생각이 나서요. 결국 나왔네요.","requires_context_qualification":true,"once_only":false},{"id":"sua_new_menu_01","event":"new_menu","text":"저번에 준비하신다던 게 이거예요? 저도 하나 먹어볼래요.","requires_context_qualification":true,"once_only":false},{"id":"sua_friendly_01","event":"friendly","text":"오늘은 팥도 주세요. 여기서 먹어보면 좋아질 수도 있을 것 같아요.","requires_context_qualification":true,"once_only":false},{"id":"sua_regular_01","event":"regular","text":"이제 집 오는 길에 가게 불부터 봐요. 켜져 있으면 괜히 반갑더라고요.","requires_context_qualification":true,"once_only":false},{"id":"sua_neighbor_01","event":"neighbor","text":"막례 할머니가 이제 저보고 새로 온 사람 아니래요. 쓰레기 버리는 날까지 다 안다고요.","requires_context_qualification":true,"once_only":true}],"dialogue_notes":"신메뉴 예고를 본 적이 없으면 ‘새 맛이 나왔네요. 저도 하나 먹어볼래요.’를 사용한다. 이웃 언급 대사는 호칭 변경 이벤트 이후에만 사용한다."}],"common_dialogues":[{"event":"first_visit","text":"안녕하세요. 붕어빵 주문할 수 있을까요?"},{"event":"waiting","text":"제 것 나오면 알려주세요."},{"event":"delayed","text":"얼마나 더 기다리면 될까요?"},{"event":"wrong_order","text":"주문한 것과 다른 것 같아요. 확인 부탁드려요."},{"event":"success","text":"감사합니다. 잘 먹을게요."},{"event":"corrected","text":"네, 맞아요. 바꿔주셔서 감사합니다."},{"event":"sold_out","text":"아쉽네요. 다음에 다시 올게요."},{"event":"timeout","text":"지금은 가봐야겠어요. 다음에 들를게요."}],"relationships":[{"pair":"막례와 도윤","description":"오래 알고 지낸 문방구집 손자"},{"pair":"막례와 윤하","description":"퇴근 시간에 자주 마주치는 동네 이웃"},{"pair":"막례와 태오","description":"사진쟁이라는 별명을 붙여준 사이"},{"pair":"막례와 민재","description":"한 바퀴 최 씨라는 별명이 생긴 사이"},{"pair":"막례와 수아","description":"이사 온 뒤 생활 정보를 알려준 사이"},{"pair":"서진과 도윤","description":"그림을 보여주고 의견을 듣는 사이"},{"pair":"태오와 도윤","description":"촬영을 자꾸 잊는 형과 이를 챙기는 동생"},{"pair":"은채와 민재","description":"아침에 자주 마주치는 퇴근자와 러너"},{"pair":"윤하와 수아","description":"비슷한 시간에 방문하며 인사를 나누는 사이"}],"companion_dialogues":[{"pair":"막례와 도윤","text":"막례: 도윤아, 오늘도 질문 보따리 들고 왔니? / 도윤: 오늘은 세 개밖에 없어요. 물어보다 늘어날 수도 있고요."},{"pair":"막례와 윤하","text":"막례: 오늘은 얼굴이 좀 폈네. / 윤하: 금요일이잖아요. 붕어빵도 있고요."},{"pair":"서진과 도윤","text":"도윤: 제 안경 너무 동그랗게 그렸어요. / 서진: 실제로도 동그란데. / 도윤: 그래도 좀 멋있게요."},{"pair":"태오와 도윤","text":"도윤: 형! 먹지 말고 사진! / 태오: 아, 맞다. 너 없으면 오늘도 놓쳤겠다."},{"pair":"막례와 태오","text":"막례: 사진쟁이 총각, 오늘은 잘 찍었어? / 태오: 네. 할머니 몫은 식기 전에 드릴게요."},{"pair":"막례와 민재","text":"막례: 최 씨, 또 한 바퀴야? / 민재: 이번에는 진짜 마지막이에요. 여기까지만요."},{"pair":"은채와 민재","text":"민재: 이제 퇴근하세요? / 은채: 네. 이제 뛰러 가세요? / 민재: 아뇨. 오늘은 먹으러만 왔어요."},{"pair":"윤하와 수아","text":"수아: 늘 같은 시간에 오시네요. / 윤하: 수아 씨도요. 이제 여기서 만나면 시계 안 봐도 되겠어요."},{"pair":"서진과 태오","text":"태오: 작가님 그림은 붕어빵이 안 식어서 좋겠어요. / 서진: 대신 못 먹어요."},{"pair":"막례와 수아","text":"막례: 동네 살 만해요? / 수아: 네. 이제 인사할 사람이 생겨서요."}],"story_events":[{"id":"story_yunha_01","npc_id":"npc_yunha","condition":"3단계, 성공 제공 3회 이상","event":"평소 주문을 기억하는 짧은 대화","result":"먼저 안부를 묻는 대사 해금"},{"id":"story_doyun_01","npc_id":"npc_doyun","condition":"2단계","event":"간식 지도 공개","result":"지도 관련 대사 해금"},{"id":"story_makrye_01","npc_id":"npc_makrye","condition":"3단계","event":"처음으로 자기 몫도 주문","result":"가게 앞에서 먹는 행동 해금"},{"id":"story_seojin_01","npc_id":"npc_seojin","condition":"3단계, 그림 대화 경험","event":"가게 그림 선물과 호칭 대화","result":"그림 기록, 서진 씨 호칭 허용","scene":"서진: 작가님이라고 부르시면 아직도 누굴 찾으시는 건가 싶어요.\n사장님: 그럼 서진 씨라고 불러도 될까요?\n서진: 네. 여기는 그림 얘기 안 하고 와도 되는 곳이면 좋겠어요."},{"id":"story_taeo_01","npc_id":"npc_taeo","condition":"3단계","event":"카메라 없는 방문","result":"촬영 없는 일상 대사 해금"},{"id":"story_eunchae_01","npc_id":"npc_eunchae","condition":"3단계","event":"쉬는 날 낮 방문","result":"휴일 방문 상태 해금"},{"id":"story_minjae_01","npc_id":"npc_minjae","condition":"3단계","event":"운동복 아닌 평상복 방문","result":"산책 손님 상태 해금"},{"id":"story_sua_01","npc_id":"npc_sua","condition":"3단계, 막례와 수아 모두 만남, 막례 2단계 이상","event":"우리 동네 수아 씨","result":"표시 명칭 변경","scene":"막례: 새로 온 아가씨라니. 이제 우리 동네 수아 씨지.\n수아: 저 이제 길 안내도 할 수 있어요. 붕어빵집 가는 길은 특히 잘 알고요."}],"story_scenes":"### 수아 호칭 변경 대사\n\n막례: 새로 온 아가씨라니. 이제 우리 동네 수아 씨지.\n\n수아: 저 이제 길 안내도 할 수 있어요. 붕어빵집 가는 길은 특히 잘 알고요.\n\n완료 처리: 수아의 표시 명칭을 ‘우리 동네 수아 씨’로 변경하고 완료 플래그를 저장한다. 메뉴, 도감, 현재 말풍선 이름표에 같은 명칭을 적용한다. 내부 ID와 기존 기록은 유지한다.\n\n### 서진 호칭 대화\n\n서진: 작가님이라고 부르시면 아직도 누굴 찾으시는 건가 싶어요.\n\n사장님: 그럼 서진 씨라고 불러도 될까요?\n\n서진: 네. 여기는 그림 얘기 안 하고 와도 되는 곳이면 좋겠어요.\n\n완료 처리: 사장님의 개인 호칭을 ‘서진 씨’로 변경한다. 화면 표시 명칭은 ‘옥탑방 오 작가’를 유지한다.","choice_events":[{"id":"choice_yunha_01","npc_id":"npc_yunha","title":"윤하의 이벤트 오늘은 한 개만","eligibility_text":"발생 조건: 윤하를 4회 이상 만났고, 서로 다른 영업일에 팥 2개 주문을 3회 이상 정확히 제공했으며, 친밀도 10 이상일 때. 이번 방문은 이벤트용으로 팥 1개를 주문한다. 평소 주문 이력으로 후보를 정하고, 방문 생성 시 이벤트 후보 주문을 예약한다. 제공 후 공통 희귀 판정을 통과하면 대화한다. 희귀 판정 실패 시에도 주문은 1개로 정상 종료한다.","prompt":"“오늘은 하나만 샀어요. 집에 바로 가기 싫어서 조금 걷다 가려고요.”","choices":[{"id":"a","text":"오늘은 발걸음 가는 쪽으로 천천히 가도 좋겠네요.","response":"“네. 오늘은 어디 도착할 생각 말고 걸어보려고요.”","reward_key":"a"},{"id":"b","text":"혼자 먹는 한 개도 맛있게 구워드렸어요.","response":"“그럼 더 천천히 먹어야겠네요. 감사합니다.”","reward_key":"b"},{"id":"c","text":"네, 조심히 들어가세요.","response":"“네. 사장님도 마감 잘하세요.”","reward_key":"c"},{"id":"wave","text":"말없이 가볍게 웃으며 인사한다.","response":"윤하는 작게 목례하고 봉투를 고쳐 쥔다.","reward_key":"wave"}],"followup_text":"후일담: A 선택 다음 방문에 “지난번에 골목 하나 더 돌아봤어요. 조용한 길이 있더라고요.” B는 “그날은 혼자서도 맛있게 먹었어요.” C는 “안녕하세요. 오늘은 평소대로 두 개요.”를 한 번 출력한다.","followups":{"a":"지난번에 골목 하나 더 돌아봤어요. 조용한 길이 있더라고요.","b":"그날은 혼자서도 맛있게 먹었어요.","c":"안녕하세요. 오늘은 평소대로 두 개요."}},{"id":"choice_doyun_01","npc_id":"npc_doyun","title":"도윤이의 이벤트 간식 지도 빈칸","eligibility_text":"발생 조건: 도윤이 3회 이상 방문, 친밀도 10 이상, 서로 다른 레시피 3종 이상 해금, 그중 2종 이상을 도윤이가 주문해 성공적으로 받은 이력이 있을 때. 도윤이의 ‘간식 지도를 그린다’는 사연이 공개되어 있어야 한다. 레시피가 부족하면 사건을 보류한다.","prompt":"“여기에 가게를 그렸는데요. 사장님 옆에 저도 그려도 돼요?”","choices":[{"id":"a","text":"그럼! 도윤이 자리도 있어야지. 어디에 서 있고 싶어?","response":"“여기요! 틀은 안 만지고 옆에서 보는 자리요!”","reward_key":"a"},{"id":"b","text":"도윤이가 그리는 지도니까 마음껏 그려도 돼.","response":"“그럼 저 조금 크게 그릴게요. 가방까지 넣어야 하거든요.”","reward_key":"b"},{"id":"c","text":"다 그리면 나도 보여줘.","response":"“네! 색칠까지 하고 보여드릴게요.”","reward_key":"c"},{"id":"wave","text":"공책을 바라보며 웃어준다.","response":"도윤이는 빈칸에 작은 별을 그리고 공책을 닫는다.","reward_key":"wave"}],"followup_text":"후일담: A는 사장님 옆에 선 자신을, B는 커다란 가방을 멘 자신을, C는 색칠한 간판을 다음 방문 대사로 소개한다. 추가 이미지 없이 대사로 구현 가능하다. 기존 10장의 간식 지도 공개 이벤트를 이미 봤어도 진행할 수 있으며, 선택 이벤트를 지도 공개의 필수 조건으로 만들지 않는다.","followups":{"a":"도윤이는 사장님 옆에 선 자신의 그림을 소개한다.","b":"도윤이는 커다란 가방을 멘 자신의 그림을 소개한다.","c":"도윤이는 색칠한 간판을 소개한다."}},{"id":"choice_makrye_01","npc_id":"npc_makrye","title":"막례 할머니의 이벤트 내 몫은 나중에","eligibility_text":"발생 조건: 친밀도 20 이상, 4개 이상 주문을 서로 다른 영업일에 2회 이상 성공 제공, 막례 외 다른 손님 3명 이상 만남, 기존 ‘자기 몫도 주문’ 이벤트 완료 전일 때.","prompt":"“옆 가게 것까지 다 샀네. 내 것은…… 집에 가서 뭐 먹으면 되지.”","choices":[{"id":"a","text":"할머니는 늘 누구 몫을 챙기시네요. 다음엔 할머니 드실 것도 잊지 마세요.","response":"“아이고, 사장님이 내 몫을 다 기억해주네. 다음에는 꼭 넣어야겠어.”","reward_key":"a"},{"id":"b","text":"할머니는 따뜻할 때 드시는 걸 좋아하시죠?","response":"“그렇지. 봉투 열자마자 먹는 게 제일 맛있지.”","reward_key":"b"},{"id":"c","text":"이웃분들이 좋아하시겠어요.","response":"“같이 먹으면 더 맛있으니까. 잘 전해줄게요.”","reward_key":"c"},{"id":"wave","text":"장바구니를 들기 편하게 봉투를 정리해준다.","response":"“고마워요. 다음에 또 들를게.”","reward_key":"wave"}],"followup_text":"후일담: A는 다음 방문에 “오늘은 내 것도 넣었어요. 사장님이 잊지 말라며.” B는 “하나는 여기서 따뜻할 때 먹고 갈게요.” C는 “옆 가게에서 잘 먹었다고 전해달래요.”를 출력한다. 대사에 맞춰 다음 주문 수량과 현장 취식 상태를 생성할 때 반영한다. 무료 지급과 구매 강요는 없다. 기존 3단계 이벤트와 같은 소재가 중복되지 않게, 이 후일담을 본 경우 기존 장면은 ‘자기 몫을 챙기는 습관이 생긴 방문’으로 바꾼다.","followups":{"a":"오늘은 내 것도 넣었어요. 사장님이 잊지 말라며.","b":"하나는 여기서 따뜻할 때 먹고 갈게요.","c":"옆 가게에서 잘 먹었다고 전해달래요."}},{"id":"choice_seojin_01","npc_id":"npc_seojin","title":"오 작가의 이벤트 마음에 안 드는 그림","eligibility_text":"발생 조건: 서진 5회 이상 방문, 친밀도 20 이상, 서로 다른 방문에서 스케치 대기 행동을 2회 이상 본 이력, 가게 그림 선물 이벤트 완료 전일 때. 플레이어가 일부러 오래 기다리게 할 필요 없이 대기 행동 시작을 관찰 이력으로 기록한다.","prompt":"“여기 그린 그림인데요. 고치다 보니까 처음 그림이 더 나았나 싶어요.”","choices":[{"id":"a","text":"저는 저기 작은 봉투가 좋아요. 평소에 보시던 게 담겨 있네요.","response":"“그걸 보셨네요. 맨날 놓이는 자리라서 그려봤어요.”","reward_key":"a"},{"id":"b","text":"잠깐 덮어두고 붕어빵부터 드실래요?","response":"“좋아요. 지금은 자꾸 같은 데만 보고 있는 것 같아요.”","reward_key":"b"},{"id":"c","text":"완성하시면 한번 보여주세요.","response":"“네. 조금만 더 만져보고 가져올게요.”","reward_key":"c"},{"id":"wave","text":"그림을 천천히 보고 고개를 끄덕인다.","response":"서진은 수첩을 덮으며 작게 웃는다.","reward_key":"wave"}],"followup_text":"후일담: A는 “그 봉투는 그대로 뒀어요. 저도 그 부분이 좋아졌거든요.” B는 “그날 쉬었다 다시 보니까 고칠 곳이 보이더라고요.” C는 “지난번 그림, 아직 그리고 있어요. 완성하면 보여드릴게요.”를 출력한다. A 대사는 그림에 봉투가 있다는 장면 설정과 연결한다.","followups":{"a":"그 봉투는 그대로 뒀어요. 저도 그 부분이 좋아졌거든요.","b":"그날 쉬었다 다시 보니까 고칠 곳이 보이더라고요.","c":"지난번 그림, 아직 그리고 있어요. 완성하면 보여드릴게요."}},{"id":"choice_taeo_01","npc_id":"npc_taeo","title":"태오 총각의 이벤트 사진 없는 기록","eligibility_text":"발생 조건: 태오 3회 이상 방문, 친밀도 10 이상, 새로운 레시피 해금 후 해당 맛을 태오에게 처음 정확히 제공한 방문일 때. 그 주문에서 촬영을 잊는 성공 연출을 보여준 뒤 대화한다. 첫 방문과 겹치면 보류하며, 이후 다른 신메뉴 주문에서 다시 후보가 된다.","prompt":"“이 맛은 처음 먹는데 또 사진을 못 찍었어요. 다 먹어놓고 무슨 맛인지 어떻게 소개하지.”","choices":[{"id":"a","text":"첫입 먹었을 때 표정은 제가 봤어요. 그 기분부터 적어보면 어때요?","response":"“오, 잠깐 말이 없어졌었죠? 그거부터 써봐야겠네요.”","reward_key":"a"},{"id":"b","text":"사진 없이 맛 이야기만 있는 글도 좋을 것 같아요.","response":"“오늘은 입으로만 찍은 후기네요. 한번 써볼게요.”","reward_key":"b"},{"id":"c","text":"다음에 오시면 먼저 찍으세요. 제가 한 번 알려드릴게요.","response":"“약속입니다! 저 또 바로 먹으려고 하면 불러주세요.”","reward_key":"c"},{"id":"wave","text":"빈 봉투를 보며 함께 웃는다.","response":"“이번 것도 맛있었다는 증거로 해두죠!”","reward_key":"wave"}],"followup_text":"후일담: A는 “그날 첫입 먹고 조용해진 얘기부터 썼어요.” B는 “사진 없는 후기 올렸어요. 생각보다 쓸 말이 많던데요.” C는 다음 촬영 연출에서 사장님이 “태오 씨, 사진 먼저요!”라고 말하고 태오가 “맞다! 감사합니다!”라고 답한다. 실제 SNS 전송이나 외부 게시 기능은 없다.","followups":{"a":"그날 첫입 먹고 조용해진 얘기부터 썼어요.","b":"사진 없는 후기 올렸어요. 생각보다 쓸 말이 많던데요.","c":"사장님: 태오 씨, 사진 먼저요!\n태오: 맞다! 감사합니다!"}},{"id":"choice_eunchae_01","npc_id":"npc_eunchae","title":"은채 씨의 이벤트 퇴근 뒤의 인사","eligibility_text":"발생 조건: ‘근무 후 방문’ 상태로 3회 이상 만남, 그중 서로 다른 영업일에 2회 이상 주문 성공, 친밀도 10 이상일 때. 휴일 상태에서는 발생하지 않는다. 시간대 기능이 있으면 아침에만 후보가 되고, 없으면 NPC 방문 상태로 판정한다.","prompt":"“다들 이제 하루 시작인데 저는 자러 가네요. 이 시간에는 인사도 좀 애매해요.”","choices":[{"id":"a","text":"은채 씨한테는 편히 쉬시라는 인사가 맞겠네요. 오늘도 잘 다녀오셨어요.","response":"“그 말 좋네요. 네, 오늘도 잘 다녀왔어요.”","reward_key":"a"},{"id":"b","text":"오늘은 푹 주무셨으면 좋겠어요.","response":"“감사합니다. 커튼 꼭 닫고 자야겠어요.”","reward_key":"b"},{"id":"c","text":"조심히 들어가세요. 다음에 또 뵐게요.","response":"“네. 사장님도 좋은 하루 보내세요.”","reward_key":"c"},{"id":"wave","text":"조용히 손을 흔들어 배웅한다.","response":"은채는 작은 손인사를 돌려주고 천천히 걸어간다.","reward_key":"wave"}],"followup_text":"후일담: A는 다음 근무 후 방문에서 “저 잘 다녀왔어요. 오늘도 퇴근입니다.” B는 “지난번엔 푹 잤어요. 오늘도 잘 자보려고요.” C는 “안녕하세요. 오늘도 집 가는 길에 들렀어요.”를 출력한다.","followups":{"a":"저 잘 다녀왔어요. 오늘도 퇴근입니다.","b":"지난번엔 푹 잤어요. 오늘도 잘 자보려고요.","c":"안녕하세요. 오늘도 집 가는 길에 들렀어요."}},{"id":"choice_minjae_01","npc_id":"npc_minjae","title":"민재 씨의 이벤트 한 바퀴를 못 채운 날","eligibility_text":"발생 조건: 민재 5회 이상 방문, 러닝 복장 방문을 3회 이상 봄, 친밀도 20 이상, 평상복 첫 방문 이벤트 완료 전일 때. 이번 방문은 운동복이지만 ‘코스 중간에 돌아옴’ 상태를 이벤트 주문 생성 시 부여한다. 실제 운동량이나 건강정보는 수집하지 않는다.","prompt":"“오늘은 한 바퀴 못 채웠어요. 중간에 돌아왔는데 붕어빵은 먹고 싶더라고요.”","choices":[{"id":"a","text":"여기는 한 바퀴 다 돌아야 들어올 수 있는 곳은 아니에요.","response":"“그러네요. 제가 혼자 입장 조건을 만들었네요.”","reward_key":"a"},{"id":"b","text":"오늘은 여기까지 산책한 걸로 해요.","response":"“좋아요. 돌아갈 때도 천천히 걸어야겠어요.”","reward_key":"b"},{"id":"c","text":"그럼 오늘도 팥으로 드릴까요?","response":"“네! 팥 생각은 끝까지 똑같더라고요.”","reward_key":"c"},{"id":"wave","text":"봉투를 건네며 가볍게 웃는다.","response":"민재는 시계를 끄고 봉투를 받아 든다.","reward_key":"wave"}],"followup_text":"후일담: A는 “오늘은 입장 조건 없이 왔습니다.” B는 “오늘도 산책 코스로 왔어요.” C는 “오늘도 팥이요. 취향은 꾸준합니다.”를 출력한다. 후일담은 러닝을 쉬는 방문 상태와 함께 생성한다. 선택 결과와 무관하게 기존 평상복 이벤트는 해금 가능하다.","followups":{"a":"오늘은 입장 조건 없이 왔습니다.","b":"오늘도 산책 코스로 왔어요.","c":"오늘도 팥이요. 취향은 꾸준합니다."}},{"id":"choice_sua_01","npc_id":"npc_sua","title":"수아 씨의 이벤트 기억해주는 가게","eligibility_text":"발생 조건: 수아를 서로 다른 영업일에 3회 이상 만남, 슈크림 주문 성공 2회 이상, 친밀도 10 이상, 마지막 만남 이후 3영업일 이상 경과한 재방문, 수아 호칭 변경 이벤트 완료 전일 때. 다른 손님들과 영업한 날을 기준으로 하며, 미접속으로 사건을 강제하지 않는다.","prompt":"“며칠 만에 왔는데 기억하시네요. 아직 동네에서 제 이름 아는 곳이 별로 없어서요.”\n\n선행 연출로 사장님이 “수아 씨, 오랜만이에요.”라고 인사한 뒤 선택창을 연다. 화면 표시 명칭은 아직 ‘새 이웃 수아 씨’다.","choices":[{"id":"a","text":"그럼 여기는 이름 아는 곳 하나 생긴 거네요. 반가워요, 수아 씨.","response":"“네. 저도 여기 오면 좀 편해요.”","reward_key":"a"},{"id":"b","text":"슈크림 좋아하시는 것도 기억해요.","response":"“맞아요. 오늘도 같은 거 먹고 싶었어요.”","reward_key":"b"},{"id":"c","text":"다음에도 편하게 들러주세요.","response":"“네. 산책할 때 또 올게요.”","reward_key":"c"},{"id":"wave","text":"눈을 맞추고 반갑게 웃는다.","response":"수아는 가방 손잡이에서 손을 놓고 작게 웃는다.","reward_key":"wave"}],"followup_text":"후일담: A는 “이름 아는 곳에 또 왔어요.” B는 “기억해주신 슈크림, 오늘도 먹으려고요.” C는 “산책하다가 들렀어요. 안녕하세요.”를 출력한다. 이 선택만으로 호칭을 변경하지 않는다. ‘우리 동네 수아 씨’는 기존 관계 이벤트에서 따로 변경한다.","followups":{"a":"이름 아는 곳에 또 왔어요.","b":"기억해주신 슈크림, 오늘도 먹으려고요.","c":"산책하다가 들렀어요. 안녕하세요."}}]}''';
